class InvalidMarksError(Exception):
    pass

def get_marks(subject):
    while True:
        try:
            m = float(input(f"{subject} marks: "))
            if not 0 <= m <= 100:
                raise InvalidMarksError("must be between 0 and 100")
        except ValueError:
            print("  Not a number, try again.")
        except InvalidMarksError as e:
            print("  Invalid:", e)
        else:
            return m

