def class_average(filename):
    try:
        f = open(filename)
    except FileNotFoundError:
        print(f"'{filename}' not found")
        return None
    valid, skipped = [], 0
    try:
        for line in f:
            try:
                valid.append(float(line))
            except ValueError:
                skipped += 1
    finally:
        f.close()
    print(f"Read {len(valid)} values, skipped {skipped}")
    return sum(valid) / len(valid)

print(class_average("missing.txt"))
print(round(class_average("scores.txt"), 2))

